//! Generated by hcc-seed. Proves the schema applies, round-trips a row per table, and uses WAL.

use capsnap::{open, open_in_memory, TABLES};

#[test]
fn schema_creates_every_table() -> rusqlite::Result<()> {
    let conn = open_in_memory()?;
    for table in TABLES {
        let n: i64 = conn.query_row(
            "SELECT count(*) FROM sqlite_master WHERE type = 'table' AND name = ?1",
            [table],
            |r| r.get(0),
        )?;
        assert_eq!(n, 1, "{table}");
    }
    Ok(())
}

#[test]
fn every_table_round_trips_a_row() -> rusqlite::Result<()> {
    let conn = open_in_memory()?;
    for (table, insert) in TABLES.iter().zip(["INSERT INTO snap (label, captured_at_utc, payload) VALUES ('seed', 'seed', X'00')"]) {
        conn.execute(insert, [])?;
        let n: i64 = conn.query_row(&format!("SELECT count(*) FROM {table}"), [], |r| r.get(0))?;
        assert_eq!(n, 1, "{table}");
    }
    Ok(())
}

#[test]
fn file_database_uses_wal() -> Result<(), Box<dyn std::error::Error>> {
    let dir = std::env::temp_dir().join(format!("capsnap-wal-{}", std::process::id()));
    std::fs::create_dir_all(&dir)?;
    let conn = open(&dir.join("capsnap.db"))?;
    let mode: String = conn.query_row("PRAGMA journal_mode", [], |r| r.get(0))?;
    assert_eq!(mode, "wal");
    drop(conn);
    std::fs::remove_dir_all(&dir)?;
    Ok(())
}
